Biographics PiP card — Doctor Strange. 6s, 1920x1080, SILENT. Use only CSS animations, no GSAP.

```html
<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<link href="https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,700;1,400&display=swap" rel="stylesheet">
<style>
*{margin:0;padding:0;box-sizing:border-box;}
body{width:1920px;height:1080px;overflow:hidden;background:#000;}
#scene{width:1920px;height:1080px;position:relative;overflow:hidden;}

#mainvid{position:absolute;top:0;left:0;width:100%;height:100%;object-fit:cover;z-index:1;}
#vignette{position:absolute;top:0;left:0;width:100%;height:100%;z-index:2;background:radial-gradient(ellipse at center,transparent 35%,rgba(0,0,0,.60) 100%);pointer-events:none;}

@keyframes pipIn{from{opacity:0;transform:translateX(24px)}to{opacity:1;transform:translateX(0)}}
@keyframes pipOut{from{opacity:1;transform:translateX(0)}to{opacity:0;transform:translateX(18px)}}
@keyframes lblIn{from{opacity:0;transform:translateX(-20px)}to{opacity:1;transform:translateX(0)}}
@keyframes lblOut{from{opacity:1;transform:translateX(0)}to{opacity:0;transform:translateX(-14px)}}

#pip{
  position:absolute;bottom:72px;right:96px;z-index:10;width:420px;
  animation: pipIn 0.7s cubic-bezier(0.22,1,0.36,1) 0.5s both,
             pipOut 0.5s ease-in 5.3s both;
}
#chaplabel{
  position:absolute;bottom:72px;left:96px;z-index:10;
  animation: lblIn 0.65s cubic-bezier(0.22,1,0.36,1) 0.7s both,
             lblOut 0.5s ease-in 5.3s both;
}

.pip-top{width:100%;height:3px;background:#8b2e2e;}
.pip-vidwrap{position:relative;width:420px;height:236px;overflow:hidden;border-left:3px solid #8b2e2e;border-right:3px solid #8b2e2e;}
.pip-vidwrap video{width:100%;height:100%;object-fit:cover;display:block;}
.pip-vidwrap .darken{position:absolute;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,.15);}
.pip-label{background:#8b2e2e;padding:10px 16px;border-left:3px solid #8b2e2e;border-right:3px solid #8b2e2e;border-bottom:3px solid #8b2e2e;}
.pip-label .role{font-family:'Playfair Display',Georgia,serif;font-size:15px;font-weight:700;color:#f0ece4;letter-spacing:.18em;text-transform:uppercase;margin:0;}
.pip-label .source{font-family:'Playfair Display',Georgia,serif;font-size:12px;font-style:italic;color:rgba(240,220,200,.80);margin:3px 0 0;letter-spacing:.08em;}

.chap-rule{display:flex;align-items:center;gap:12px;margin-bottom:10px;}
.chap-rule span.line{display:inline-block;width:40px;height:1px;background:rgba(139,46,46,.8);}
.chap-rule span.text{font-family:'Playfair Display',Georgia,serif;font-size:12px;font-style:italic;color:rgba(139,46,46,.9);letter-spacing:.4em;text-transform:uppercase;}
.chap-title{font-family:'Playfair Display',Georgia,serif;font-size:28px;font-weight:700;color:#f0ece4;letter-spacing:.04em;margin:0;text-shadow:0 2px 20px rgba(0,0,0,.8);}
</style>
</head>
<body>
<div id="scene">
  <video id="mainvid" autoplay muted loop playsinline><source src="{{mainVid}}" type="video/mp4"></video>
  <div id="vignette"></div>

  <div id="pip">
    <div class="pip-top"></div>
    <div class="pip-vidwrap">
      <video autoplay muted loop playsinline><source src="{{pipVid}}" type="video/mp4"></video>
      <div class="darken"></div>
    </div>
    <div class="pip-label">
      <p class="role">DOCTOR STRANGE</p>
      <p class="source">Marvel Studios &middot; 2016</p>
    </div>
  </div>

  <div id="chaplabel">
    <div class="chap-rule">
      <span class="line"></span>
      <span class="text">HOLLYWOOD &amp; THE STRANGE</span>
    </div>
    <p class="chap-title">The Sorcerer</p>
  </div>
</div>
</body>
</html>
```
